def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    # The 1 markers define diagonal segments; retain unrelated marks.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i+1:]:
            if abs(r2-r1) == abs(c2-c1):
                sr = 1 if r2 > r1 else -1
                sc = 1 if c2 > c1 else -1
                for k in range(abs(r2-r1)+1):
                    r, c = r1+k*sr, c1+k*sc
                    if grid[r][c] != 6:
                        out[r][c] = 1
    # A 6 lying on a diagonal between two 1s extends along the other diagonal.
    for r, c in sixes:
        diagonal_type = None
        for i, (r1, c1) in enumerate(ones):
            for r2, c2 in ones[i+1:]:
                if abs(r2-r1) != abs(c2-c1):
                    continue
                if r1-c1 == r2-c2 == r-c and min(r1,r2) <= r <= max(r1,r2):
                    diagonal_type = 'positive'
                elif r1+c1 == r2+c2 == r+c and min(r1,r2) <= r <= max(r1,r2):
                    diagonal_type = 'negative'
        if diagonal_type:
            for k in range(-max(h,w), max(h,w)+1):
                rr, cc = (r+k, c-k) if diagonal_type == 'positive' else (r+k, c+k)
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 1:
                    out[rr][cc] = 6
    return out

def transform(grid):
    out = [row[:] for row in grid]
