            if abs(r2-r1) == abs(c2-c1):
                sr = 1 if r2 > r1 else -1
                sc = 1 if c2 > c1 else -1
                for k in range(abs(r2-r1)+1):
                    r, c = r1+k*sr, c1+k*sc
                    if grid[r][c] != 6:
                        out[r][c] = 1
    # A 6 lying on a diagonal between two 1s extends along the other diagonal.
    for r, c in sixes:
        diagonal_type = None
        for i, (r1, c1) in enumerate(ones):
            for r2, c2 in ones[i+1:]:
                if abs(r2-r1) != abs(c2-c1):
